using App.Common;
using App.Entities;

namespace App.Repositories;

/// <summary>Keeps patients rows in memory, for tests and for trying the services without a database.</summary>
public class MemoryPatientRepository : IPatientRepository
{
    private readonly Dictionary<string, Patient> rows = [];

    /// <summary>The key of a row, as a list of its key values.</summary>
    private static object[] KeyOf(Patient row) => [row.Id];

    private static string KeyText(Patient row) => string.Join("|", KeyOf(row));

    /// <summary>Orders two keys value by value.</summary>
    private static int Compare(IReadOnlyList<object> a, IReadOnlyList<object> b)
    {
        for (var index = 0; index < a.Count; index++)
        {
            var order = Comparer<object>.Default.Compare(a[index], b[index]);
            if (order != 0) return order;
        }
        return 0;
    }

    private IEnumerable<Patient> Visible() =>
        rows.Values.Where(row => true).OrderBy(KeyOf, Comparer<object[]>.Create((a, b) => Compare(a, b)));

    public Task<Patient?> FindByIdAsync(string id)
    {
        return Task.FromResult(Visible().FirstOrDefault(row => Equals(row.Id, id)));
    }

    public Task<CursorPage<Patient>> ListAsync(IReadOnlyList<object>? after, int limit)
    {
        var rows = Visible().Where(row => after is null || Compare(KeyOf(row), after) > 0).ToList();
        var items = rows.Take(limit).ToList();
        return Task.FromResult(new CursorPage<Patient>(items, rows.Count > limit ? KeyOf(items[^1]) : null));
    }

    public Task<Patient?> FindByDocumentAsync(string document)
    {
        return Task.FromResult(Visible().FirstOrDefault(row => Equals(row.Document, document)));
    }

    public Task<List<Patient>> FindAllByBirthAsync(DateTime birth)
    {
        return Task.FromResult(Visible().Where(row => Equals(row.Birth, birth)).ToList());
    }

    public Task<Patient> InsertAsync(Patient entity)
    {
        entity.Id ??= MongoDB.Bson.ObjectId.GenerateNewId().ToString();
        rows[KeyText(entity)] = entity;
        return Task.FromResult(entity);
    }

    public Task<Patient> UpdateAsync(Patient entity)
    {
        rows[KeyText(entity)] = entity;
        return Task.FromResult(entity);
    }

    public Task DeleteAsync(Patient entity)
    {
        rows.Remove(KeyText(entity));
        return Task.CompletedTask;
    }

    public Task<Patient?> AddContactAsync(string id, Patient.ContactDocument contact)
    {
        var found = Visible().FirstOrDefault(row => Equals(row.Id, id));
        if (found is null) return Task.FromResult<Patient?>(null);
        found.Contacts = [..found.Contacts ?? [], contact];
        found.Version = (found.Version ?? 0) + 1;
        return Task.FromResult<Patient?>(found);
    }

    public Task<Patient?> RemoveContactAsync(string id, int position, int size)
    {
        var found = Visible().FirstOrDefault(row => Equals(row.Id, id));
        if (found is null || (found.Contacts?.Count ?? 0) != size) return Task.FromResult<Patient?>(null);
        found.Contacts = (found.Contacts ?? []).Where((_, index) => index != position).ToList();
        found.Version = (found.Version ?? 0) + 1;
        return Task.FromResult<Patient?>(found);
    }
}

