using System.Runtime.CompilerServices;
using App;
using App.Common;
using App.Entities;
using App.Errors;
using MongoDB.Bson;
using MongoDB.Driver;

namespace App.Repositories;

/// <summary>Keeps patients documents in the database, through the MongoDB driver. It runs in the transaction already open, when there is one.</summary>
public class MongoPatientRepository(Db db) : IPatientRepository
{
    private const string Collection = "patients";

    /// <summary>The document each entity was read from: a change writes only the fields that differ</summary>
    private static readonly ConditionalWeakTable<Patient, BsonDocument> Read = [];

    /// <summary>The fields a change may write</summary>
    private static readonly string[] Fields = ["name", "birth", "weight", "balance", "document", "photo", "visits", "blood", "contacts", "insurance", "version"];

    public async Task<Patient?> FindByIdAsync(string id)
    {
        if (!ObjectId.TryParse(id, out _)) return null;
        var found = await db.Find(Collection, Builders<Patient>.Filter.Eq(row => row.Id, id)).FirstOrDefaultAsync();
        return found is null ? null : Loaded(found);
    }

    public async Task<CursorPage<Patient>> ListAsync(IReadOnlyList<object>? after, int limit)
    {
        var filter = Builders<Patient>.Filter.Empty;
        if (after is not null) filter &= Builders<Patient>.Filter.Gt(row => row.Id, (string)after[0]);
        var rows = (await db.Find(Collection, filter).Sort(Builders<Patient>.Sort.Ascending(row => row.Id)).Limit(limit + 1).ToListAsync()).Select(Loaded).ToList();
        var items = rows.Take(limit).ToList();
        return new CursorPage<Patient>(items, rows.Count > limit ? [items[^1].Id] : null);
    }

    public async Task<Patient?> FindByDocumentAsync(string document)
    {
        var found = await db.Find(Collection, Builders<Patient>.Filter.Eq(row => row.Document, document)).FirstOrDefaultAsync();
        return found is null ? null : Loaded(found);
    }

    public async Task<List<Patient>> FindAllByBirthAsync(DateTime birth)
    {
        return (await db.Find(Collection, Builders<Patient>.Filter.Eq(row => row.Birth, birth)).Sort(Builders<Patient>.Sort.Ascending(row => row.Id)).ToListAsync()).Select(Loaded).ToList();
    }

    public async Task<Patient> InsertAsync(Patient entity)
    {
        entity.Id ??= MongoDB.Bson.ObjectId.GenerateNewId().ToString();
        await db.InsertAsync("Patient", Collection, entity);
        return Loaded(entity);
    }

    public async Task<Patient> UpdateAsync(Patient entity)
    {
        var now = entity.ToBsonDocument();
        var changes = Documents.Changes(Read.TryGetValue(entity, out var before) ? before : null, now, Fields);
        if (changes.ElementCount > 0) await db.UpdateAsync<Patient>("Patient", Collection, new BsonDocument("_id", now["_id"]), changes);
        return Loaded(entity);
    }

    public async Task DeleteAsync(Patient entity)
    {
        await db.DeleteAsync("Patient", Collection, Builders<Patient>.Filter.Eq(row => row.Id, entity.Id));
    }

    public async Task<Patient?> AddContactAsync(string id, Patient.ContactDocument contact)
    {
        if (!ObjectId.TryParse(id, out _)) return null;
        var change = new BsonDocument { ["$push"] = new BsonDocument("contacts", contact.ToBsonDocument()), ["$inc"] = new BsonDocument("version", 1) };
        var filter = new BsonDocument { ["_id"] = new ObjectId(id) };
        var changed = await db.ChangeAsync<Patient>("Patient", Collection, filter, change);
        return changed is null ? null : Loaded(changed);
    }

    public async Task<Patient?> RemoveContactAsync(string id, int position, int size)
    {
        if (!ObjectId.TryParse(id, out _)) return null;
        var head = new BsonDocument("$slice", new BsonArray { "$contacts", position });
        var tail = new BsonDocument("$slice", new BsonArray { "$contacts", position + 1, Math.Max(size, 1) });
        BsonDocument[] change = [new("$set", new BsonDocument { ["contacts"] = new BsonDocument("$concatArrays", new BsonArray { head, tail }), ["version"] = new BsonDocument("$add", new BsonArray { "$version", 1 }) })];
        var filter = new BsonDocument { ["_id"] = new ObjectId(id), ["contacts"] = new BsonDocument("$size", size) };
        var changed = await db.ChangeAsync<Patient>("Patient", Collection, filter, change);
        return changed is null ? null : Loaded(changed);
    }

    /// <summary>The same entity, with what it is stored as kept to tell its changes.</summary>
    private static Patient Loaded(Patient entity)
    {
        Read.AddOrUpdate(entity, entity.ToBsonDocument());
        return entity;
    }
}

