using System.Globalization;
using App;
using App.Common;
using App.Dtos;
using App.Entities;
using App.Errors;

namespace App.Services;

/// <summary>Operations on patients. Each write runs in its own transaction.</summary>
public class PatientService(IUnitOfWork unitOfWork)
{
    private readonly IUnitOfWork uow = unitOfWork;

    /// <summary>Checks the values against the rules of the "patients" table, and the rows they point to; throws ValidationFailedException with every problem.</summary>
    private static async Task ValidateAsync(IUnitOfWork uow, Dictionary<string, object?> values, Patient? current)
    {
        var creating = current is null;
        var errors = new List<FieldError>();
        {
            var value = values.GetValueOrDefault("Name");
            if (value is null)
            {
                if (creating || values.ContainsKey("Name")) errors.Add(new FieldError("name", "is required"));
            }
            else
            {
                if (value is string text && text.Length > 80) errors.Add(new FieldError("name", "is longer than 80 characters"));
                if (!(Convert.ToString(value, CultureInfo.InvariantCulture)!.Length >= 2)) errors.Add(new FieldError("name", "must have >= 2 characters"));
            }
        }
        {
            var value = values.GetValueOrDefault("Birth");
            if (value is null)
                if (creating || values.ContainsKey("Birth")) errors.Add(new FieldError("birth", "is required"));
        }
        {
            var value = values.GetValueOrDefault("Visits");
            if (value is null)
            {
                if (creating || values.ContainsKey("Visits")) errors.Add(new FieldError("visits", "is required"));
            }
            else
            {
                if (!(Number(value) >= 0m)) errors.Add(new FieldError("visits", "must be >= 0"));
            }
        }
        {
            var value = values.GetValueOrDefault("Blood");
            if (value is not null)
            {
                if (!new[] { "A", "B", "O" }.Contains(Convert.ToString(value, CultureInfo.InvariantCulture))) errors.Add(new FieldError("blood", "must be one of: A, B, O"));
            }
        }
        {
            var value = values.GetValueOrDefault("Contacts");
            if (value is null)
            {
                if (creating || values.ContainsKey("Contacts")) errors.Add(new FieldError("contacts", "is required"));
            }
            else
            {
                var document = (List<Patient.ContactDocument>)value;
                if (document is not null)
                {
                    for (var i0 = 0; i0 < document.Count; i0++)
                    {
                        if (document[i0] is null) errors.Add(new FieldError("contacts" + "." + i0, "is required"));
                        else CheckContact(document[i0], "contacts" + "." + i0, errors);
                    }
                }
            }
        }
        {
            var value = values.GetValueOrDefault("Insurance");
            if (value is not null)
            {
                var document = (Patient.InsuranceDocument)value;
                if (document is not null) CheckInsurance(document, "insurance", errors);
            }
        }
        if (errors.Count > 0) throw new ValidationFailedException("Patient", errors);
    }

    /// <summary>A number of any type, to compare it.</summary>
    private static decimal Number(object value) => Convert.ToDecimal(value, CultureInfo.InvariantCulture);

    /// <summary>Values that must be unique are not taken by another row.</summary>
    private static async Task CheckUniqueAsync(IUnitOfWork uow, Dictionary<string, object?> values, Patient? current)
    {
        {
            var document = values.TryGetValue("Document", out var givenDocument) ? (string?)givenDocument : current?.Document;
            if (document is not null)
            {
                var other = await uow.Patients.FindByDocumentAsync(document);
                if (other is not null && (current is null || !Equals(other.Id, current.Id)))
                    throw new ConflictException("Patient", "document is already taken", ["Document"]);
            }
        }
    }

    /// <summary>Every check before a write: the values, the rows they point to, the unique values.</summary>
    private static async Task CheckAsync(IUnitOfWork uow, Dictionary<string, object?> values, Patient? current)
    {
        await ValidateAsync(uow, values, current);
        await CheckUniqueAsync(uow, values, current);
    }

    /// <summary>Sets the given values on the entity.</summary>
    private static void Apply(Patient entity, Dictionary<string, object?> values)
    {
        if (values.TryGetValue("Name", out var name)) entity.Name = (string)name!;
        if (values.TryGetValue("Birth", out var birth)) entity.Birth = (DateTime)birth!;
        if (values.TryGetValue("Weight", out var weight)) entity.Weight = (double?)weight;
        if (values.TryGetValue("Balance", out var balance)) entity.Balance = (decimal?)balance;
        if (values.TryGetValue("Document", out var document)) entity.Document = (string?)document;
        if (values.TryGetValue("Photo", out var photo)) entity.Photo = (byte[]?)photo;
        if (values.TryGetValue("Visits", out var visits)) entity.Visits = (int)visits!;
        if (values.TryGetValue("Blood", out var blood)) entity.Blood = (string?)blood;
        if (values.TryGetValue("Contacts", out var contacts)) entity.Contacts = (List<Patient.ContactDocument>)contacts!;
        if (values.TryGetValue("Insurance", out var insurance)) entity.Insurance = (Patient.InsuranceDocument?)insurance;
        if (values.TryGetValue("Version", out var version)) entity.Version = (int?)version;
    }

    /// <summary>The Patient with this key; NotFoundException when there is none.</summary>
    private static async Task<Patient> FindAsync(IUnitOfWork uow, string id) =>
        await uow.Patients.FindByIdAsync(id) ?? throw new NotFoundException("Patient", id);

    /// <summary>The Patient as services return it.</summary>
    private static PatientRead Read(Patient entity) => new(entity.Id, entity.Name, entity.Birth, entity.Weight, entity.Balance, entity.Document, entity.Photo, entity.Visits, entity.Blood, entity.Contacts, entity.Insurance, entity.Version);

    /// <summary>The values an update gives, by field.</summary>
    private static Dictionary<string, object?> Given(PatientUpdate changes)
    {
        var values = new Dictionary<string, object?>();
        values["Name"] = changes.Name;
        values["Birth"] = changes.Birth;
        values["Weight"] = changes.Weight;
        values["Balance"] = changes.Balance;
        values["Document"] = changes.Document;
        values["Photo"] = changes.Photo;
        values["Visits"] = changes.Visits;
        values["Blood"] = changes.Blood;
        values["Contacts"] = changes.Contacts;
        values["Insurance"] = changes.Insurance;
        values["Version"] = changes.Version;
        return values;
    }

    /// <summary>What a Patient.ContactDocument does not follow of its rules, each with the path of its field.</summary>
    private static void CheckContact(Patient.ContactDocument value, string path, List<FieldError> errors)
    {
        if (value.Kind is null) errors.Add(new FieldError(path + ".kind", "is required"));
        if (value.Kind is not null && !new[] { "phone", "email" }.Contains(value.Kind)) errors.Add(new FieldError(path + ".kind", "must be one of: phone, email"));
        if (value.Value is null) errors.Add(new FieldError(path + ".value", "is required"));
    }

    /// <summary>What a Patient.InsuranceDocument does not follow of its rules, each with the path of its field.</summary>
    private static void CheckInsurance(Patient.InsuranceDocument value, string path, List<FieldError> errors)
    {
    }

    /// <summary>Stores a new Patient after checking it.</summary>
    public async Task<PatientRead> CreatePatientAsync(PatientCreate data)
    {
        var values = new Dictionary<string, object?>();
        if (data.Name is not null) values["Name"] = data.Name;
        values["Birth"] = data.Birth;
        if (data.Weight is not null) values["Weight"] = data.Weight;
        if (data.Balance is not null) values["Balance"] = data.Balance;
        if (data.Document is not null) values["Document"] = data.Document;
        if (data.Photo is not null) values["Photo"] = data.Photo;
        values["Visits"] = data.Visits;
        if (data.Blood is not null) values["Blood"] = data.Blood;
        if (data.Contacts is not null) values["Contacts"] = data.Contacts;
        if (data.Insurance is not null) values["Insurance"] = data.Insurance;
        if (data.Version is not null) values["Version"] = data.Version;
        return await this.uow.TransactionAsync(async uow =>
        {
            await CheckAsync(uow, values, null);
            var entity = new Patient();
            Apply(entity, values);
            return Read(await uow.Patients.InsertAsync(entity));
        });
    }

    /// <summary>The Patient with this key; NotFoundException when there is none.</summary>
    public async Task<PatientRead> GetPatientAsync(string id) => Read(await FindAsync(uow, id));

    /// <summary>A page of patients after the key after (null for the first page), by primary key.</summary>
    public async Task<CursorPage<PatientRead>> ListPatientsAsync(IReadOnlyList<object>? after, int limit) => (await uow.Patients.ListAsync(after, limit)).Map(Read);

    /// <summary>Changes the given values of a Patient, read at version.</summary>
    public async Task<PatientRead> UpdatePatientAsync(string id, PatientUpdate changes, int version)
    {
        var values = Given(changes);
        return await this.uow.TransactionAsync(async uow =>
        {
            var current = await FindAsync(uow, id);
            if (!Equals(current.Version, version))
                throw new ConflictException("Patient", "was changed by someone else since it was read", ["Version"]);
            await CheckAsync(uow, values, current);
            Apply(current, values);
            current.Version = version + 1;
            return Read(await uow.Patients.UpdateAsync(current));
        });
    }

    /// <summary>Deletes a Patient.</summary>
    public async Task DeletePatientAsync(string id, int version)
    {
        await this.uow.TransactionAsync(async uow =>
        {
            var current = await FindAsync(uow, id);
            if (!Equals(current.Version, version))
                throw new ConflictException("Patient", "was changed by someone else since it was read", ["Version"]);
            await uow.Patients.DeleteAsync(current);
        });
    }

    /// <summary>The Patient with this document, or null.</summary>
    public async Task<PatientRead?> FindPatientByDocumentAsync(string document) => await uow.Patients.FindByDocumentAsync(document) is { } entity ? Read(entity) : null;

    /// <summary>Adds an item to contacts, read at version.</summary>
    public async Task<PatientRead> AddContactAsync(string id, Patient.ContactDocument contact, int version)
    {
        var errors = new List<FieldError>();
        CheckContact(contact, "contacts", errors);
        if (errors.Count > 0) throw new ValidationFailedException("Patient", errors);
        return await this.uow.TransactionAsync(async uow =>
        {
            var current = await FindAsync(uow, id);
            if (!Equals(current.Version, version))
                throw new ConflictException("Patient", "was changed by someone else since it was read", ["Version"]);
            return Read(await uow.Patients.AddContactAsync(id, contact) ?? throw new NotFoundException("Patient", id));
        });
    }

    /// <summary>Removes an item from contacts, by its position, read at version.</summary>
    public async Task<PatientRead> RemoveContactAsync(string id, int position, int version)
    {
        return await this.uow.TransactionAsync(async uow =>
        {
            var current = await FindAsync(uow, id);
            if (!Equals(current.Version, version))
                throw new ConflictException("Patient", "was changed by someone else since it was read", ["Version"]);
            if (current.Contacts is null || position < 0 || position >= current.Contacts.Count) throw new NotFoundException("Contact", position);
            return Read(await uow.Patients.RemoveContactAsync(id, position, current.Contacts.Count) ?? throw new ConflictException("Patient", "was changed by someone else since it was read", ["Contacts"]));
        });
    }
}

