using App;
using App.Common;
using App.Dtos;
using App.Entities;
using App.Errors;

namespace App.Services;

/// <summary>Operations on rooms. Each write runs in its own transaction.</summary>
public class RoomService(IUnitOfWork unitOfWork)
{
    private readonly IUnitOfWork uow = unitOfWork;

    /// <summary>Checks the values against the rules of the "rooms" table, and the rows they point to; throws ValidationFailedException with every problem.</summary>
    private static async Task ValidateAsync(IUnitOfWork uow, Dictionary<string, object?> values, Room? current)
    {
        var creating = current is null;
        var errors = new List<FieldError>();
        {
            var value = values.GetValueOrDefault("Code");
            if (value is null)
                if (creating || values.ContainsKey("Code")) errors.Add(new FieldError("code", "is required"));
        }
        if (errors.Count > 0) throw new ValidationFailedException("Room", errors);
    }

    /// <summary>Every check before a write: the values, the rows they point to, the unique values.</summary>
    private static async Task CheckAsync(IUnitOfWork uow, Dictionary<string, object?> values, Room? current)
    {
        await ValidateAsync(uow, values, current);
    }

    /// <summary>Sets the given values on the entity.</summary>
    private static void Apply(Room entity, Dictionary<string, object?> values)
    {
        if (values.TryGetValue("Code", out var code)) entity.Code = (string)code!;
        if (values.TryGetValue("Beds", out var beds)) entity.Beds = (long?)beds;
    }

    /// <summary>The Room with this key; NotFoundException when there is none.</summary>
    private static async Task<Room> FindAsync(IUnitOfWork uow, string id) =>
        await uow.Rooms.FindByIdAsync(id) ?? throw new NotFoundException("Room", id);

    /// <summary>The Room as services return it.</summary>
    private static RoomRead Read(Room entity) => new(entity.Id, entity.Code, entity.Beds);

    /// <summary>The values an update gives, by field.</summary>
    private static Dictionary<string, object?> Given(RoomUpdate changes)
    {
        var values = new Dictionary<string, object?>();
        values["Code"] = changes.Code;
        values["Beds"] = changes.Beds;
        return values;
    }

    /// <summary>Stores a new Room after checking it.</summary>
    public async Task<RoomRead> CreateRoomAsync(RoomCreate data)
    {
        var values = new Dictionary<string, object?>();
        if (data.Code is not null) values["Code"] = data.Code;
        if (data.Beds is not null) values["Beds"] = data.Beds;
        return await this.uow.TransactionAsync(async uow =>
        {
            await CheckAsync(uow, values, null);
            var entity = new Room();
            Apply(entity, values);
            return Read(await uow.Rooms.InsertAsync(entity));
        });
    }

    /// <summary>The Room with this key; NotFoundException when there is none.</summary>
    public async Task<RoomRead> GetRoomAsync(string id) => Read(await FindAsync(uow, id));

    /// <summary>A page of rooms after the key after (null for the first page), by primary key.</summary>
    public async Task<CursorPage<RoomRead>> ListRoomsAsync(IReadOnlyList<object>? after, int limit) => (await uow.Rooms.ListAsync(after, limit)).Map(Read);

    /// <summary>Changes the given values of a Room.</summary>
    public async Task<RoomRead> UpdateRoomAsync(string id, RoomUpdate changes)
    {
        var values = Given(changes);
        return await this.uow.TransactionAsync(async uow =>
        {
            var current = await FindAsync(uow, id);
            await CheckAsync(uow, values, current);
            Apply(current, values);
            return Read(await uow.Rooms.UpdateAsync(current));
        });
    }

    /// <summary>Deletes a Room.</summary>
    public async Task DeleteRoomAsync(string id)
    {
        await this.uow.TransactionAsync(async uow =>
        {
            var current = await FindAsync(uow, id);
            await uow.Rooms.DeleteAsync(current);
        });
    }
}

