/// <summary>The repository of the "patients" table, against the test database.</summary>
public class PatientRepositoryTests : IAsyncLifetime
{
    private Db db = null!;

    /// <summary>The repositories over the test database, opened empty for every test</summary>
    private MongoUnitOfWork uow = null!;

    public async ValueTask InitializeAsync()
    {
        db = await TestDatabase.OpenAsync();
        uow = new MongoUnitOfWork(db);
    }

    public async ValueTask DisposeAsync() => await db.DisposeAsync();

    [Fact]
    public async Task IsStoredAndReadBack()
    {
        var stored = await Factories.AddPatientAsync(uow, 1);
        var found = await uow.Patients.FindByIdAsync(stored.Id);
        Assert.NotNull(found);
        Assert.Equal(stored.Id, found.Id);
        if (stored.Document is not null) Assert.NotNull(await uow.Patients.FindByDocumentAsync(stored.Document));
    }

    [Fact]
    public async Task ListsRowsByKey()
    {
        await Factories.AddPatientAsync(uow, 1);
        await Factories.AddPatientAsync(uow, 2);
        var first = await uow.Patients.ListAsync(null, 1);
        Assert.Single(first.Items);
        Assert.NotNull(first.Next);
        var second = await uow.Patients.ListAsync(first.Next, 1);
        Assert.Single(second.Items);
        Assert.Null(second.Next);
    }

    [Fact]
    public async Task IsDeleted()
    {
        var stored = await Factories.AddPatientAsync(uow, 1);
        await uow.Patients.DeleteAsync(stored);
        Assert.Null(await uow.Patients.FindByIdAsync(stored.Id));
    }

    [Fact]
    public async Task AddsAndRemovesOneItemOfContacts()
    {
        var stored = await Factories.AddPatientAsync(uow, 1);
        var before = stored.Contacts?.Count ?? 0;
        Patient.ContactDocument item = Factories.NewPatientContact(7);
        var added = await uow.Patients.AddContactAsync(stored.Id, item);
        Assert.Equal(before + 1, added!.Contacts!.Count);
        var removed = await uow.Patients.RemoveContactAsync(stored.Id, before, added.Contacts!.Count);
        Assert.Equal(before, removed!.Contacts!.Count);
        Assert.Null(await uow.Patients.RemoveContactAsync(stored.Id, 0, before + 5));
    }
}

/// <summary>The service of the "patients" table, on the in-memory repositories.</summary>
public class PatientServiceTests
{
    private readonly MemoryUnitOfWork uow = new();

    [Fact]
    public async Task CreatesAValidRow()
    {
        var service = new PatientService(uow);
        var n = 100;
        var row = Factories.NewPatient(1);
        var created = await service.CreatePatientAsync(CreateOf(row));
        var found = await service.GetPatientAsync(created.Id);
        Assert.Equal(created.Id, found.Id);
    }

    [Fact]
    public async Task RefusesAMissingValue()
    {
        var service = new PatientService(uow);
        var n = 100;
        var row = Factories.NewPatient(1);
        row.Name = null!;
        var error = await Assert.ThrowsAsync<ValidationFailedException>(() => service.CreatePatientAsync(CreateOf(row)));
        Assert.Equal(new[] { "name" }, error.Errors.Select(item => item.Field));
    }

    [Fact]
    public async Task RefusesARepeatedUniqueValue()
    {
        var service = new PatientService(uow);
        var n = 100;
        var row = Factories.NewPatient(1);
        var first = await service.CreatePatientAsync(CreateOf(row));
        var again = Factories.NewPatient(2);
        again.Document = first.Document;
        await Assert.ThrowsAsync<ConflictException>(() => service.CreatePatientAsync(CreateOf(again)));
    }

    [Fact]
    public async Task KeepsItsOwnUniqueValue()
    {
        var service = new PatientService(uow);
        var n = 100;
        var row = Factories.NewPatient(1);
        var created = await service.CreatePatientAsync(CreateOf(row));
        await service.UpdatePatientAsync(created.Id, new PatientUpdate(row.Name, row.Birth, row.Weight, row.Balance, created.Document, row.Photo, row.Visits, row.Blood, row.Contacts, row.Insurance, row.Version), created.Version!.Value);
    }

    [Fact]
    public async Task SaysWhenARowIsMissing()
    {
        var service = new PatientService(uow);
        await Assert.ThrowsAsync<NotFoundException>(() => service.GetPatientAsync("ffffffffffffffffffffffff"));
    }

    [Fact]
    public async Task DeletesARow()
    {
        var service = new PatientService(uow);
        var n = 100;
        var row = Factories.NewPatient(1);
        var created = await service.CreatePatientAsync(CreateOf(row));
        await service.DeletePatientAsync(created.Id, created.Version!.Value);
        await Assert.ThrowsAsync<NotFoundException>(() => service.GetPatientAsync(created.Id));
    }

    [Fact]
    public async Task AddsAndRemovesOneItemOfContacts()
    {
        var service = new PatientService(uow);
        var n = 100;
        var row = Factories.NewPatient(1);
        var created = await service.CreatePatientAsync(CreateOf(row));
        var before = created.Contacts?.Count ?? 0;
        Patient.ContactDocument item = Factories.NewPatientContact(7);
        var added = await service.AddContactAsync(created.Id, item, created.Version!.Value);
        Assert.Equal(before + 1, added.Contacts!.Count);
        var removed = await service.RemoveContactAsync(created.Id, before, added.Version!.Value);
        Assert.Equal(before, removed.Contacts!.Count);
        await Assert.ThrowsAsync<NotFoundException>(() => service.RemoveContactAsync(created.Id, 99, removed.Version!.Value));
    }

    /// <summary>The create DTO of a row the factories made.</summary>
    private static PatientCreate CreateOf(Patient row) => new(row.Name, row.Birth, row.Weight, row.Balance, row.Document, row.Photo, row.Visits, row.Blood, row.Contacts, row.Insurance, row.Version);
}

